from collections import deque

def bfs_at_depth(graph, start, target_depth):
    # BFS to find nodes at exactly target_depth
    # Returns set of nodes at exactly that depth (not including start or intermediate)

    visited = set([start])  # Track visited to avoid cycles
    queue = deque([(start, 0)])  # (node, depth)
    depth_nodes = defaultdict(set)  # depth -> set of nodes

    while queue:
        node, depth = queue.popleft()

        if depth == target_depth:
            # We've reached target depth, add to results
            depth_nodes[depth].add(node)
            # Don't expand further from target depth
            continue

        # Expand neighbors
        for neighbor in graph.get(node, []):
            if neighbor not in visited or depth + 1 <= target_depth:
                # For BFS at exact depth, we need to allow revisiting if we're going deeper
                # But we track by depth level
                new_depth = depth + 1
                if new_depth <= target_depth:
                    if neighbor not in [n for d in range(new_depth) for n in depth_nodes[d]] and neighbor != start:
                        queue.append((neighbor, new_depth))
                        depth_nodes[new_depth].add(neighbor)

    return depth_nodes[target_depth]

# Actually, let me use a cleaner approach - level by level
def bfs_depth_levels(graph, start):
    """Returns a dict of depth -> set of nodes at that depth"""
