    visited = {start}

    while True:
        next_level = set()
        for node in levels[current_depth]:
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    next_level.add(neighbor)
                    visited.add(neighbor)

        if not next_level:
            break

        current_depth += 1
        levels[current_depth] = next_level

        # Safety limit
        if current_depth > 100:
            break

    return levels

